function auOut($code,$ok,$msg,$extra=array()){while(ob_get_level()>0){@ob_end_clean();}http_response_code($code);header('Content-Type: application/json; charset=utf-8');echo json_encode(array_merge(array('success'=>$ok,'message'=>$msg),$extra),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function auPost($k,$d=''){return isset($_POST[$k])&&!is_array($_POST[$k])?trim((string)$_POST[$k]):$d;}
function auTable(PDO $pdo,$t){$s=$pdo->prepare("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t");$s->execute(array(':t'=>$t));return (int)$s->fetchColumn()>0;}
function auColumn(PDO $pdo,$t,$c){$s=$pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t AND COLUMN_NAME=:c");$s->execute(array(':t'=>$t,':c'=>$c));return (int)$s->fetchColumn()>0;}
function auJson($s,$default=array()){if(is_array($s))return $s;$x=json_decode((string)$s,true);return is_array($x)?$x:$default;}
function auAudit(PDO $pdo,$tenant,$branch,$user,$action,$id,$old,$new){if(function_exists('tenantAuditLog')){tenantAuditLog($pdo,$action,$tenant,$branch>0?$branch:null,$user,'tenant_automation',$id,$old,$new);}}
function auRequireSchema(PDO $pdo){foreach(array('platform_automation_entities','platform_automation_triggers','platform_automation_conditions','platform_automation_actions','tenant_automations','tenant_automation_conditions','tenant_automation_actions','tenant_automation_runs') as $t){if(!auTable($pdo,$t))auOut(500,false,'Automation database is not installed. Run database/automation-system.sql first.');}}
function auStatuses($entity){if($entity==='quote')return array('draft','awaiting response','changes requested','approved','converted','rejected','expired','archived');if($entity==='invoice')return array('draft','sent','viewed','partially paid','paid','overdue','written off','cancelled','archived');if($entity==='request')return array('new','open','assessment required','quote required','scheduled','closed','cancelled','archived');return array();}
